private void newConnectionId(Cur cur, ByteArrayOutputStream out) {
    long sequence = cur.varint();
    long retirePriorTo = cur.varint();
    int cidLength = cur.u8();
    byte[] cid = cur.take(cidLength);
    byte[] token = cur.take(16);
    if (cidLength < 1 || cidLength > 20) throw new Fail(ENCODING, 0);
    if (retirePriorTo > sequence) throw new Fail(ENCODING, 0);
    out.writeBytes(vi(sequence));
    out.writeBytes(vi(retirePriorTo));
    out.write(cidLength);
    out.writeBytes(cid);
    out.writeBytes(token);

    String key = Main.hex(cid);
    PeerCid observed = peerObserved.get(sequence);
    if (observed != null && (!Arrays.equals(observed.cid, cid) || !Arrays.equals(observed.token, token))) {
        throw new Fail(VIOLATION, 0);
    }
    Long owner = cidOwner.get(key);
    if (owner != null && owner != sequence) throw new Fail(VIOLATION, 0);
    if (observed == null) {
        peerObserved.put(sequence, new PeerCid(cid, token));
        journal.add(() -> peerObserved.remove(sequence));
    }
    if (owner == null) {
        cidOwner.put(key, sequence);
        journal.add(() -> cidOwner.remove(key));
    }
    if (retirePriorTo > retireThreshold) {
        final long previous = retireThreshold;
        retireThreshold = retirePriorTo;
        journal.add(() -> retireThreshold = previous);
    }
    ArrayList<Long> dropped = new ArrayList<>();
    Iterator<Long> active = peerActive.iterator();
    while (active.hasNext()) {
        long candidate = active.next();
        if (candidate >= retireThreshold) break;
        dropped.add(candidate);
        active.remove();
    }
    if (!dropped.isEmpty()) {
        journal.add(
                () -> {
                    for (long restored : dropped) peerActive.add(restored);
                });
    }
    if (sequence >= retireThreshold && peerActive.add(sequence)) {
        journal.add(() -> peerActive.remove(sequence));
    }
    if (peerActive.size() > cidLimit) throw new Fail(CID_LIMIT, 0);
}

private void retireConnectionId(Cur cur, ByteArrayOutputStream out, Pkt pkt) {
    long sequence = cur.varint();
    out.writeBytes(vi(sequence));
    if (sequence >= localCids.length) throw new Fail(VIOLATION, 0);
    if (sequence == pkt.destination) throw new Fail(VIOLATION, 0);
    if (!retiredLocal.covers(sequence)) retiredLocal.add(sequence, sequence + 1, journal);
}

